const CATALOG_BY_ID=new Map(window.DM_CATALOG.foods.map(f=>[f.id,f]));
const CATALOG_BY_NAME=new Map(window.DM_CATALOG.foods.map(f=>[f.name,f]));
function catalogFoodByName(name){return CATALOG_BY_NAME.get(name)||CATALOG_BY_NAME.get(CATALOG_RENAMES[name])||null}
function isUserFood(f){return !!f&&!CATALOG_BY_ID.has(f.id)&&!catalogFoodByName(f.name)&&/^u\d/.test(String(f.id))}
function syncCatalog(db){
  const remap={},extra=[];
  const referenced=new Set();
  Object.values(db.menus||{}).forEach(m=>Object.values(m||{}).flat().forEach(r=>r&&referenced.add(r.foodId)));
  ((db.favorites&&db.favorites.foods)||[]).forEach(id=>referenced.add(id));
  (Array.isArray(db.foods)?db.foods:[]).forEach(f=>{
    if(!f||!f.name)return;
    if(isUserFood(f)){if(!f.category)f.category=foodCategoryByName(f.name);extra.push(f);return;}
    const target=catalogFoodByName(f.name);
    if(target){if(target.id!==f.id)remap[f.id]=target.id;return;}
    if(CATALOG_BY_ID.has(f.id))return;
    // Удалённая из каталога позиция: оставляем скрытой, только если на неё ссылается история.
    if(referenced.has(f.id))extra.push({...f,hidden:true});
  });
  db.foods=window.DM_CATALOG.foods.map(f=>({...f})).concat(extra);
  const fix=id=>remap[id]||id;
  Object.values(db.menus||{}).forEach(m=>Object.values(m||{}).flat().forEach(r=>{if(r&&remap[r.foodId])r.foodId=remap[r.foodId]}));
  if(db.favorites&&Array.isArray(db.favorites.foods))db.favorites.foods=[...new Set(db.favorites.foods.map(fix))];
  (db.recipes||[]).forEach(r=>{if(Array.isArray(r.ingredients))r.ingredients.forEach(i=>{if(Array.isArray(i)&&CATALOG_RENAMES[i[0]])i[0]=CATALOG_RENAMES[i[0]]})});
  db.appMeta=db.appMeta||{};db.appMeta.appVersion=APP_VERSION;db.appMeta.catalogVersion=window.DM_CATALOG.version;
}
function isFoodVisible(f){return !!f&&!f.hidden}
function foodSrc(f){const p=f&&f.image;if(!p)return '';if(!/^assets\//.test(p))return p;const c=CATALOG_BY_NAME.get(f.name);const h=f.h||(c&&c.image===p&&c.h);return p+'?h='+(h||APP_VERSION)}
function foodIcon(name){const f=db.foods.find(x=>x.name===name);const p=foodSrc(f);if(!p)return '🍽️';return `<img src="${p}" alt="${name}" loading="lazy" style="object-fit:contain;width:100%;height:100%;background:#fff;border-radius:12px;" onerror="this.onerror=null;this.src='assets/foods/_fallback.jpg';this.alt='Изображение недоступно';">`}
