<div class="fdTiles">${tile('Углеводы',f.c,'г')}${tile('ХЕ',(f.c/xe).toFixed(2),'')}${tile('Калории',f.kcal,'ккал')}${tile('Белки',f.p,'г')}${tile('Жиры',f.f,'г')}${tile('БЖЕ',bje(f.p,f.f).toFixed(2),'')}</div>
