function helpTab(tab){document.getElementById('helpQuick').style.display=tab==='quick'?'block':'none';document.getElementById('helpGuide').style.display=tab==='guide'?'block':'none';document.getElementById('helpFaq').style.display=tab==='faq'?'block':'none';if(tab==='faq')renderFAQ()}
function renderFAQ(){let q=(document.getElementById('faqQ')?.value||'').trim().toLowerCase(),arr=FAQ_ITEMS.filter(x=>!q||(x[0]+' '+x[1]).toLowerCase().replace(/[«»"„“]/g,'').replace(/ё/g,'е').includes(q.replace(/[«»"„“]/g,'').replace(/ё/g,'е')));let el=document.getElementById('faqList');if(!el)return;el.innerHTML=arr.length?arr.map((x,i)=>`<details class="mini" style="margin:8px 0"><summary><b>${x[0]}</b></summary><p>${x[1]}</p></details>`).join(''):'<div class="muted">По вашему запросу ничего не найдено. Попробуйте другие слова.</div>'}
function buildWeekFromFavorites(){ensureFavorites();let fav=db.foods.filter(f=>isFavoriteFood(f.id));if(fav.length<3){alert('Добавьте в Избранное хотя бы 3 продукта/блюда, чтобы сформировать недельную заготовку. Для лучшего разнообразия желательно больше.');return}let start=prompt('Дата начала недели (ГГГГ-ММ-ДД):',document.getElementById('day').value||today())||'';if(!/^\d{4}-\d{2}-\d{2}$/.test(start))return;if(!weekOverwriteOk(start))return;let used=[];let pick=(day,meal)=>{let candidates=fav.filter(f=>!used.slice(-2).includes(f.id)&&canAddToMeal(f.id,meal));if(!candidates.length)candidates=fav.filter(f=>canAddToMeal(f.id,meal));if(!candidates.length)return null;let f=candidates[(day*3+meals.indexOf(meal))%candidates.length];used.push(f.id);return f};for(let di=0;di<7;di++){let d=new Date(start+'T12:00:00');d.setDate(d.getDate()+di);let iso=d.toISOString().slice(0,10);db.menus[iso]=Object.fromEntries(meals.map(m=>[m,[]]));['Завтрак','Обед','Ужин'].forEach((meal,mi)=>{let f=pick(di,meal);if(f)db.menus[iso][meal].push({id:crypto.randomUUID(),foodId:f.id,g:mi===0?150:120})})}db.templatePreferences=db.templatePreferences||{};db.templatePreferences.lastFavoriteWeekStart=start;db.templatePreferences.favoriteWeekGeneratedAt=new Date().toISOString();save();alert('Неделя из Избранного сформирована. Проверьте состав, порции и при необходимости измените отдельные дни.');document.getElementById('day').value=start;show('menu')}
