function templateFoodName(name){let map={'Овощи':'Помидор','Салат':'Огурец','Ягоды':'Клубника','Куриная грудка':'Курица отварная','Куриное бедро без кожи':'Куриное бедро отварное','Индейка филе':'Индейка отварная','Говядина постная':'Говядина отварная','Свинина постная':'Свинина отварная','Баранина постная':'Баранина отварная'};return map[name]||name}
