function addTemplateItem(date,meal,name,g){let f=db.foods.find(x=>x.name===templateFoodName(name));if(!f)return false;if(!canAddToMeal(f.id,meal))return false;db.menus[date]=db.menus[date]||Object.fromEntries(meals.map(m=>[m,[]]));db.menus[date][meal].push({id:crypto.randomUUID(),foodId:f.id,g});return true}
function weekOverwriteOk(start){let n=0;for(let di=0;di<7;di++){let d=new Date(start+'T12:00:00');d.setDate(d.getDate()+di);let m=db.menus[d.toISOString().slice(0,10)];if(m&&Object.values(m).some(a=>Array.isArray(a)&&a.length))n++}return !n||confirm('На '+n+' '+(n===1?'день':n<5?'дня':'дней')+' этой недели уже составлено меню.\n\nОно будет полностью заменено новым. Продолжить?')}
function applyWeekTemplate(){let idx=+(document.getElementById('weekTemplate').value||0),start=document.getElementById('weekStart').value||today(),tpl=WEEKLY_TEMPLATES[idx];if(!tpl)return;if(!weekOverwriteOk(start))return;let d=new Date(start+'T12:00:00'),miss=[];tpl.days.forEach((day,di)=>{let date=new Date(d);date.setDate(d.getDate()+di);let iso=date.toISOString().slice(0,10);db.menus[iso]=Object.fromEntries(meals.map(m=>[m,[]]));Object.entries(day).forEach(([m,its])=>its.forEach(([n,g])=>{let f=db.foods.find(x=>x.name===templateFoodName(n));if(f&&db.menus[iso][m])db.menus[iso][m].push({id:crypto.randomUUID(),foodId:f.id,g});else miss.push(n)}))});db.templatePreferences={lastWeeklyTemplate:idx,lastWeekStart:start};save();alert(miss.length?'Шаблон применён частично: не найдены в базе — '+[...new Set(miss)].join(', ')+'.':'Недельный шаблон применён. Откройте «Конструктор меню» и при необходимости измените продукты и порции.');document.getElementById('day').value=start;show('menu')}
