  const W=900,H=280,pl=40,pr=16,pt=14,pb=44,n=values.length,ymax=Math.max(12,Math.ceil(Math.max(...values.map(x=>x.v))/2)*2+1),X=i=>pl+(n<2?(W-pl-pr)/2:i*(W-pl-pr)/(n-1)),Y=g=>pt+(1-g/ymax)*(H-pt-pb);
