function saveSettings(){db.settings.target=+setTarget.value||5.5;db.settings.icr=+setICR.value||'';db.settings.isf=+setISF.value||'';db.settings.carb=+setCarb.value||0;save();alert('Настройки сохранены')}function saveLocaleSettings(){db.preferences=db.preferences||{};db.preferences.language=setLanguage.value||'ru';db.preferences.region=setRegion.value||'KG';db.preferences.units=db.preferences.units||{};db.preferences.units.glucose=setGlucoseUnit.value||'mmol/L';db.preferences.languageSync=db.preferences.languageSync||{};db.preferences.languageSync.mode=setLanguageSync.value||'device';if(db.preferences.languageSync.mode==='shared')db.preferences.languageSync.sharedLanguage=db.preferences.language;save();window.DMI18N.apply();renderSettings();}function renderSettings(){setTarget.value=db.profile.target||db.settings.target||'';setICR.innerHTML=icrOptions(db.profile.icr||db.settings.icr||'');setISF.innerHTML=isfOptions(db.profile.isf||db.settings.isf||'');setCarb.value=db.settings.carb||'';setLanguage.value=db.preferences?.language||'ru';setRegion.value=db.preferences?.region||'KG';setGlucoseUnit.value=db.preferences?.units?.glucose||'mmol/L';setLanguageSync.value=db.preferences?.languageSync?.mode||'device';window.DMI18N.apply()}
function setTransferStatus(msg,ok=false){let el=document.getElementById('transferStatus');if(el){el.textContent=msg;el.className=ok?'ok':'muted'}}
