function exportPortableJson(){let env=core.transfer.createEnvelope(db,{sourceInstallationId:db.commercial?.installation?.id||db.device?.id||null,sourcePlatform:db.device?.platform||'web-desktop',encryption:'none'});DMBackup.download(JSON.stringify(env,null,2),'my-diabetes-portable-backup-'+today()+'.json');setTransferStatus('Переносимая копия создана. Храните её в защищённом месте.',true)}
async function createEncryptedBackup(){try{if(!DMBackup.hasCrypto())throw new Error('На этом устройстве недоступно шифрование Web Crypto.');let p1=prompt('Придумайте пароль для резервной копии. Пароль не сохраняется в приложении.');if(!p1)return;let p2=prompt('Повторите пароль.');if(p1!==p2)throw new Error('Пароли не совпадают.');let env=core.transfer.createEnvelope(db,{sourceInstallationId:db.commercial?.installation?.id||db.device?.id||null,sourcePlatform:db.device?.platform||'web-desktop',encryption:'AES-256-GCM'});let file=await DMBackup.encryptEnvelope(env,p1);DMBackup.download(JSON.stringify(file,null,2),'my-diabetes-encrypted-backup-'+today()+'.json');setTransferStatus('Зашифрованная копия создана. Пароль известен только вам.',true)}catch(e){setTransferStatus(e.message||'Не удалось создать копию.')}}
function importData(e){let f=e.target.files[0];if(!f)return;if(!confirm('Загрузить данные из файла «'+f.name+'»?\n\nВСЕ текущие данные на этом устройстве (меню, дневник, профиль, анализы) будут заменены содержимым файла. Отменить это нельзя.\n\nЕсли не уверены, сначала сохраните резервную копию кнопкой экспорта.')){e.target.value='';return}let r=new FileReader();r.onload=()=>{try{let raw=JSON.parse(r.result);let env=raw.manifest?raw:raw.data?.manifest?raw.data:null;if(env&&env.manifest){db=core.transfer.restore(db,env)}else{db=core.migrate(raw)}save();location.reload()}catch(err){alert('Ошибка импорта: '+(err.message||'проверьте файл'))}};r.readAsText(f)}
async function importEncryptedBackup(e){let f=e.target.files[0];if(!f)return;try{let raw=JSON.parse(await f.text());if(raw.format!=='my-diabetes-encrypted-backup')throw new Error('Это не зашифрованная копия приложения.');if(!confirm('Восстановить данные из резервной копии «'+f.name+'»?\n\nВСЕ текущие данные на этом устройстве будут заменены данными из копии. Отменить это нельзя.')){e.target.value='';return}let p=prompt('Введите пароль резервной копии.');if(!p)return;let env=await DMBackup.decryptEnvelope(raw,p);let check=core.transfer.validateEnvelope(env);if(!check.valid)throw new Error('Проверка целостности не пройдена: '+check.errors.join(', '));db=core.transfer.restore(db,env);save();setTransferStatus('Данные восстановлены. Проверьте медицинские параметры перед использованием калькулятора.',true);setTimeout(()=>location.reload(),900)}catch(err){setTransferStatus(err.message||'Не удалось восстановить копию.')}}


