function openMedicalHint(id){
  let t=(typeof GLOSSARY_TERMS!=='undefined'?GLOSSARY_TERMS:[]).find(x=>x.id===id||x.abbr===id||String(x.en||'').toLowerCase()===String(id).toLowerCase());
  if(!t){const q=String(id).toLowerCase();t=(typeof GLOSSARY_TERMS!=='undefined'?GLOSSARY_TERMS:[]).find(x=>String(x.en||'').toLowerCase().replace(/[«»"„“]/g,'').replace(/ё/g,'е').includes(q.replace(/[«»"„“]/g,'').replace(/ё/g,'е'))||String(x.ru||'').toLowerCase().replace(/[«»"„“]/g,'').replace(/ё/g,'е').includes(q.replace(/[«»"„“]/g,'').replace(/ё/g,'е')));}
  if(!t){const X=(window.MED_HINTS||{})[id];if(!X)return;t={id:id,ru:X.title||id};}
  const overlay=document.getElementById('medicalHintOverlay'), body=document.getElementById('medicalHintBody'), title=document.getElementById('medicalHintTitle');
  if(!overlay||!body||!title)return;
  const add=(tag,text,cls)=>{if(!text)return;const el=document.createElement(tag);if(cls)el.className=cls;el.textContent=text;body.appendChild(el);};
  body.replaceChildren(); const H0=(window.MED_HINTS||{})[t.id]; title.textContent=H0?(H0.title||t.ru||t.abbr):(t.abbr&&t.abbr!=='—'?t.abbr+' — ':'')+(t.ru||t.en||'Справочная подсказка');
  const H=(window.MED_HINTS||{})[t.id];
  if(H){add('p',H.text);if(H.tip){add('div','Как заполнить','medHintLabel');add('p',H.tip);}}
  else{add('p',t.short||'');
  if(t.simple){add('div','Проще говоря','medHintLabel');add('p',t.simple);}
  if(t.detail&&t.detail.indexOf(t.simple||'\u0000')!==0){add('div','Подробнее','medHintLabel');add('p',t.detail);}}
  const meta=[];if(t.units&&t.units!=='—'&&!(H&&/бланк|дата|дд\.мм|зависит|ЕД/.test(t.units)))meta.push('Единицы: '+t.units);if(t.used&&!H)meta.push('Используется: '+t.used);
  if(meta.length)add('div',meta.join(' · '),'medHintMeta');
  overlay.classList.add('open');document.body.style.overflow='hidden';
  const close=document.querySelector('.medHintClose');if(close)close.focus();
}
