function renderCurrentGlucose(){const el=document.getElementById('sGlucose'),st=document.getElementById('glucoseStatus');if(!el||!st)return;const day=document.getElementById('day')?.value||today();
const a=(db.diary||[]).filter(x=>x.date<=day&&Number.isFinite(+x.g)).sort((x,y)=>(x.date+(x.time||'')).localeCompare(y.date+(y.time||'')));const x=a[a.length-1];
const lb=document.getElementById('sGlucoseLabel');if(lb)lb.textContent='Текущая зарегистрированная глюкоза';if(!x){el.textContent='—';st.className='statusGood';st.textContent='● Данные появятся после записи';try{window.DMCgm&&DMCgm.paint()}catch(e){}return}
const g=+x.g;el.textContent=g.toFixed(1);const when=(x.date===day?'сегодня':x.date)+(x.time?' в '+x.time:'');
const [cls,txt]=g<3.9?['statusLow','● Низкая — ниже 3,9']:g>10?['statusHigh','● Выше 10']:['statusGood','● В диапазоне 3,9–10'];st.className=cls;st.textContent=txt+' · '+when;try{window.DMCgm&&DMCgm.paint()}catch(e){}}

