(function(){try{const m=db.medical;if(m&&m.ins&&!m.scheme&&/\d\s*(ЕД|ед)/.test(m.ins)&&/—/.test(m.ins)){m.scheme=m.ins.replace(/;\s*/g,';\n');m.ins='';save()}}catch(e){}})();

/* v63.95: в «Лекарства» попадают только препараты, не процедуры и режим */
const NON_DRUG=/реабилит|лфк|массаж|магнит|физио|электрофорез|тепло|процедур|диет|стол\s*№|режим|наблюден|контрол|консультац|школ[аеу]\s+диабет|обучен|госпитализ|санатор|прогулк|занят|сон\b|питани|самоконтрол|осмотр|анализ/i;
function isDrugItem(x){x=String(x||'').replace(/^\s*[*•-]\s*/,'');return !!x&&!NON_DRUG.test(x.split(/[:—]/)[0])}
(function(){try{const m=db.medical;if(m&&Array.isArray(m.medications)&&m.medications.some(x=>x&&x.name&&!isDrugItem(x.name))){m.medications=m.medications.filter(x=>!(x&&x.name&&!isDrugItem(x.name)));save()}}catch(e){}})();

/* v63.95: проверка новой версии — при возвращении в приложение и раз в 15 минут */
(function(){
  let shown=false,last=0;
  async function check(){
    if(shown||!navigator.onLine||Date.now()-last<60000)return;last=Date.now();
    try{
      const r=await fetch('index.html?check='+Date.now(),{cache:'no-store'});if(!r.ok)return;
      const m=(await r.text()).match(/js\/app\.js\?v=(v[\d.]+)/);if(!m)return;
      const num=v=>v.replace(/^v/,'').split('.').map(Number),a=num(m[1]),b=num(APP_VERSION);
      const newer=a[0]>b[0]||(a[0]===b[0]&&(a[1]||0)>(b[1]||0))||(a[0]===b[0]&&a[1]===b[1]&&(a[2]||0)>(b[2]||0));
      if(newer)banner(m[1]);
    }catch(e){}
  }
  function banner(v){
    shown=true;const d=document.createElement('div');d.id='updBanner';
    d.innerHTML='<div><b>Вышла новая версия</b><br><span>Записи не пропадут.</span></div><button class="btn">Обновить</button><button class="updX" aria-label="Позже">×</button>';
    d.querySelector('.btn').onclick=async()=>{d.querySelector('.btn').textContent='Обновляю…';try{if(window.cloudPushNow)await cloudPushNow(false)}catch(e){}try{const r=await navigator.serviceWorker?.getRegistration();await r?.update()}catch(e){}location.reload()};
    d.querySelector('.updX').onclick=()=>{d.remove();setTimeout(()=>{shown=false},30*60000)};
    document.body.appendChild(d);
  }
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')check()});
  window.addEventListener('focus',check);window.addEventListener('online',check);
  setInterval(()=>{if(document.visibilityState==='visible')check()},15*60000);
  setTimeout(check,5000);
})();
